import { ChangeDetectionStrategy, Component, DestroyRef, inject, signal } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { Subject, of, timer, throwError } from 'rxjs';
import { catchError, debounceTime, delay, distinctUntilChanged, switchMap, tap } from 'rxjs/operators';

interface Result {
  id: number;
  name: string;
  email: string;
}

const FAKE_DATA: Result[] = [
  { id: 1, name: 'Alice Johnson', email: 'alice@example.com' },
  { id: 2, name: 'Bob Smith', email: 'bob@example.com' },
  { id: 3, name: 'Charlie Kim', email: 'charlie@example.com' },
  { id: 4, name: 'Diana Lopez', email: 'diana@example.com' },
  { id: 5, name: 'Ethan Brown', email: 'ethan@example.com' },
  { id: 6, name: 'Fiona Patel', email: 'fiona@example.com' }
];

@Component({
  selector: 'app-root',
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  readonly query = signal('');
  // The search pipeline writes these from timer callbacks; as signals they still refresh the OnPush view.
  readonly results = signal<Result[]>([]);
  readonly isLoading = signal(false);
  readonly error = signal<string | null>(null);

  private readonly searchTerm$ = new Subject<string>();
  private readonly destroyRef = inject(DestroyRef);

  constructor() {
    this.setupSearchStream();
  }

  onQueryChange(value: string): void {
    this.query.set(value);
    this.searchTerm$.next(value);
  }

  private setupSearchStream(): void {
    this.searchTerm$
      .pipe(
        debounceTime(500),
        distinctUntilChanged(),
        tap((term) => {
          if (!term.trim()) {
            this.results.set([]);
            this.isLoading.set(false);
          } else {
            this.isLoading.set(true);
          }
          this.error.set(null);
        }),
        switchMap((term) => {
          const trimmed = term.trim();
          if (!trimmed) {
            return of([]);
          }

          return this.fakeApiSearch(trimmed).pipe(
            catchError((err: unknown) => {
              this.error.set(err instanceof Error ? err.message : 'Something went wrong.');
              this.isLoading.set(false);
              return of([]);
            })
          );
        }),
        takeUntilDestroyed(this.destroyRef)
      )
      .subscribe((results: Result[]) => {
        this.results.set(results);
        this.isLoading.set(false);
      });
  }

  // Fake API: filters the in-memory array and responds after a delay.
  private fakeApiSearch(term: string) {
    const trimmed = term.trim().toLowerCase();
    const delayMs = 600;

    if (!trimmed) {
      return of([]).pipe(delay(delayMs));
    }

    const filtered = FAKE_DATA.filter((item) => {
      const name = item.name.toLowerCase();
      const email = item.email.toLowerCase();
      return name.includes(trimmed) || email.includes(trimmed);
    });

    // Deliberately fail for the query "error" so students can see error handling.
    if (trimmed === 'error') {
      return timer(delayMs).pipe(
        switchMap(() => throwError(() => new Error('Fake API error')))
      );
    }

    return of(filtered).pipe(delay(delayMs));
  }
}
